CREATE TABLE `biz_expense` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `expense_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支出单号',
  `expense_date` date NOT NULL COMMENT '支出日期',
  `expense_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支出类型',
  `expense_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '支出名称',
  `amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '金额',
  `express_company` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '快递公司',
  `shipment_count` int DEFAULT NULL COMMENT '发货数量',
  `related_sale_id` bigint DEFAULT NULL COMMENT '关联销售ID',
  `related_order_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '关联订单号',
  `independent_flag` tinyint NOT NULL DEFAULT '1' COMMENT '是否独立经营费用：1是，0否',
  `payment_method` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '付款方式',
  `voucher_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '凭证号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_biz_expense_no` (`expense_no`),
  KEY `idx_biz_expense_date` (`expense_date`),
  KEY `idx_biz_expense_type` (`expense_type`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='经营支出';
