--
-- Table structure for table `biz_inventory_log`
--

DROP TABLE IF EXISTS `biz_inventory_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_inventory_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `batch_id` bigint NOT NULL COMMENT '批次ID',
  `business_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '业务类型',
  `business_id` bigint DEFAULT NULL COMMENT '业务ID',
  `business_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '业务单号',
  `change_quantity` int NOT NULL COMMENT '变更数量',
  `before_quantity` int NOT NULL COMMENT '变更前数量',
  `after_quantity` int NOT NULL COMMENT '变更后数量',
  `unit_cost` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '单位成本',
  `business_date` date NOT NULL COMMENT '业务日期',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_biz_inventory_log_product_id` (`product_id`),
  KEY `idx_biz_inventory_log_batch_id` (`batch_id`),
  KEY `idx_biz_inventory_log_business` (`business_type`,`business_id`)
) ENGINE=InnoDB AUTO_INCREMENT=278 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='库存流水';
/*!40101 SET character_set_client = @saved_cs_client */;

