--
-- Table structure for table `biz_purchase`
--

DROP TABLE IF EXISTS `biz_purchase`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_purchase` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `purchase_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '采购单号',
  `platform` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '采购平台',
  `platform_order_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '平台订单号',
  `supplier_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '供应商',
  `seller_account` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '卖家账号/昵称',
  `purchase_date` datetime NOT NULL COMMENT 'purchase time',
  `item_count` int NOT NULL DEFAULT '1' COMMENT '采购件数，二手单件采购通常为1',
  `purchase_status` tinyint NOT NULL DEFAULT '1' COMMENT '采购状态：1待到货，2已到货，3已取消',
  `goods_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '商品总额',
  `freight_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '采购运费',
  `discount_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '优惠金额',
  `other_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '其他费用',
  `pay_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '实付金额',
  `invoice_status` tinyint NOT NULL DEFAULT '0' COMMENT '发票状态',
  `invoice_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发票抬头',
  `invoice_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发票号码',
  `invoice_date` date DEFAULT NULL COMMENT '发票日期',
  `invoice_file_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发票原始文件名',
  `invoice_file_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '发票附件路径',
  `payment_method` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '付款方式',
  `received_at` datetime DEFAULT NULL COMMENT '到货时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_biz_purchase_no` (`purchase_no`),
  KEY `idx_biz_purchase_platform_order_no` (`platform_order_no`),
  KEY `idx_biz_purchase_date` (`purchase_date`)
) ENGINE=InnoDB AUTO_INCREMENT=149 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='采购主表';
/*!40101 SET character_set_client = @saved_cs_client */;

