--
-- Table structure for table `biz_purchase_item`
--

DROP TABLE IF EXISTS `biz_purchase_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_purchase_item` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `purchase_id` bigint NOT NULL COMMENT '采购ID',
  `product_id` bigint NOT NULL COMMENT '商品ID',
  `condition_desc` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '成色/瑕疵描述',
  `device_no` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '单台设备唯一编号，如IMEI/序列号',
  `quantity` int NOT NULL COMMENT '数量',
  `unit_price` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '单价',
  `total_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '明细金额',
  `check_status` tinyint NOT NULL DEFAULT '0' COMMENT '验货状态：0未验货，1通过，2异常',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0否，1是',
  PRIMARY KEY (`id`),
  KEY `idx_biz_purchase_item_purchase_id` (`purchase_id`),
  KEY `idx_biz_purchase_item_product_id` (`product_id`),
  KEY `idx_biz_purchase_item_device_no` (`device_no`)
) ENGINE=InnoDB AUTO_INCREMENT=152 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='采购明细';
/*!40101 SET character_set_client = @saved_cs_client */;

