--
-- Table structure for table `biz_sale_record`
--

DROP TABLE IF EXISTS `biz_sale_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `biz_sale_record` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `record_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '销售记录号',
  `business_date` date NOT NULL COMMENT '业务日期',
  `platform` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '销售平台',
  `platform_order_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '平台订单号',
  `buyer_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '买家姓名',
  `buyer_phone` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '买家电话',
  `total_sale_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '销售总额',
  `total_cost_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '商品总成本',
  `platform_fee` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '平台手续费',
  `express_fee` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '快递费',
  `package_fee` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '包装费',
  `promotion_fee` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '推广费',
  `refund_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '退款金额',
  `other_expense` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '其他费用',
  `fee_config` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '费用配置JSON，记录费率、无忧卖和费用明细',
  `received_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '实际到账金额',
  `profit_amount` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '利润',
  `payment_status` tinyint NOT NULL DEFAULT '0' COMMENT '付款状态',
  `shipment_status` tinyint NOT NULL DEFAULT '0' COMMENT '发货状态',
  `express_company` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '快递公司',
  `express_no` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '快递单号',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除：0否，1是',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_biz_sale_record_no` (`record_no`),
  KEY `idx_biz_sale_record_platform_order_no` (`platform_order_no`),
  KEY `idx_biz_sale_record_business_date` (`business_date`)
) ENGINE=InnoDB AUTO_INCREMENT=103 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='销售记录';
/*!40101 SET character_set_client = @saved_cs_client */;

